# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VEDA HACCI (HİCRETİN 10. YILI / 632) VE ÖNEMİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Veda Haccı Süreci (Zilkade - Zilhicce 10)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Peygamberimizin ilk ve son haccıdır.</text>\n  <text x="180" y="120" text-anchor="middle" font-size="11" fill="#334155">• Medine\'den yüz bini aşkın sahabi ile</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" fill="#334155">Zülhuleyfe mikat sınırında ihrama girildi.</text>\n  <text x="180" y="162" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e3a8a">• Hac İbadetinin Uygulamalı Öğretimi:</text>\n  <text x="180" y="182" text-anchor="middle" font-size="11" fill="#334155">"Hac ibadetinizin kurallarını benden öğreniniz."</text>\n  <text x="180" y="206" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">• Mekân: Arafat Vadisi (Cebel-i Rahme)</text>\n  <text x="180" y="224" text-anchor="middle" font-size="11" fill="#334155">Tarih: 9 Zilhicce 10 (6 Mart 632, Cuma günü)</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Dinin Kemâle Ermesi (Mâide Suresi, 3. Ayet)</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">Arafat\'ta Veda Haccı esnasında nazil olan ayet:</text>\n  <text x="520" y="122" text-anchor="middle" font-size="11" fill="#166534">"Bugün sizin için dininizi kemâle erdirdim</text>\n  <text x="520" y="140" text-anchor="middle" font-size="11" fill="#166534">(olgunlaştırdım), üzerinizdeki nimetimi</text>\n  <text x="520" y="158" text-anchor="middle" font-size="11" fill="#166534">tamamladım ve sizin için din olarak</text>\n  <text x="520" y="176" text-anchor="middle" font-size="11" font-weight="bold" fill="#14532d">İslam\'dan razı oldum." (Mâide, 3)</text>\n  <text x="520" y="206" text-anchor="middle" font-size="11" fill="#334155">Tebliğ görevinin tamamlandığının ve</text>\n  <text x="520" y="224" text-anchor="middle" font-size="11" fill="#334155">Peygamberimizin vefatının yaklaştığının işaretidir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">VEDA HUTBESİ\'NDEKİ EVRENSEL İNSAN HAKLARI İLKELERİ</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Temel Haklar ve Cahiliye Adetlerinin İptali</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">1. Can, Mal ve Namus Dokunulmazlığı:</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#334155">Kanlarınız, mallarınız ve ırzlarınız birbirinize haramdır.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">2. Emanetlerin Sahibine İadesi:</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#334155">Üzerinde emanet bulunan onu sahibine teslim etsin.</text>\n  <text x="180" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">3. Faizin (Riba) ve Kan Davalarının Kaldırılması:</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" fill="#334155">İlk kaldırılan: Abbas b. Abdülmuttalib\'in faizi ve</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" fill="#334155">Rebîa b. Hâris\'in kan davasıdır.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Eşitlik, Aile Hakları ve İki Emanet</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">4. Kadın ve Aile Hakları:</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">Kadınlar Allah\'ın emanetidir; karşılıklı hak ve</text>\n  <text x="520" y="132" text-anchor="middle" font-size="11" fill="#334155">sorumluluklar gözetilmelidir.</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">5. Irkçılığın Reddi ve Eşitlik (Takva Ölçüsü):</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#334155">Arap\'ın Arap olmayana üstünlüğü yoktur; üstünlük takvadadır.</text>\n  <text x="520" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">6. Suçun Şahsiliği ve İki Emanet (Sekaleyn):</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" fill="#334155">Bırakılan iki emanet: Allah\'ın Kitabı (Kur\'an) ve Sünnet.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">PEYGAMBERİMİZİN (SAV) RAHATSIZLANMASI VE VEFATI (8 HAZİRAN 632)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="180" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Son Günleri ve Vefatı (12 Rebîülevvel 11)</text>\n  <text x="180" y="96" text-anchor="middle" font-size="11" fill="#334155">• Veda Haccı\'ndan Medine\'ye döndükten sonra</text>\n  <text x="180" y="114" text-anchor="middle" font-size="11" fill="#334155">Safer ayının sonlarında rahatsızlandı.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Namaz İmamlığı Görevi:</text>\n  <text x="180" y="156" text-anchor="middle" font-size="11" fill="#334155">Mescid-i Nebi\'ye çıkamadığı günlerde namazları</text>\n  <text x="180" y="174" text-anchor="middle" font-size="11" fill="#334155">kıldırma görevini Hz. Ebû Bekir\'e (ra) verdi.</text>\n  <text x="180" y="198" text-anchor="middle" font-size="11" font-weight="bold" fill="#9f1239">• Refîk-i A\'lâ\'ya Kavuşma:</text>\n  <text x="180" y="216" text-anchor="middle" font-size="11" fill="#334155">8 Haziran 632\'de Hz. Âişe\'nin odasında vefat etti.</text>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Ravza-i Mutahhara ve Sahabenin Metaneti</text>\n  <text x="520" y="96" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Kabr-i Şerifi (Hücre-i Saadet):</text>\n  <text x="520" y="114" text-anchor="middle" font-size="11" fill="#334155">Vefat ettiği odaya (Mescid-i Nebi içinde) defnedildi.</text>\n  <text x="520" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#155e75">• Hz. Ebû Bekir\'in (ra) Tarihî Konuşması:</text>\n  <text x="520" y="156" text-anchor="middle" font-size="11" fill="#334155">Hz. Ömer dahil büyük üzüntü ve şaşkınlık yaşayan</text>\n  <text x="520" y="174" text-anchor="middle" font-size="11" fill="#334155">sahabilere Âl-i İmrân suresi 144. ayeti okuyarak</text>\n  <text x="520" y="192" text-anchor="middle" font-size="11" fill="#334155">Hz. Muhammed\'in de bir elçi ve beşer olduğunu,</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#0891b2">Allah\'ın ise daima diri (el-Hayy) olduğunu hatırlattı.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
